export function ConfirmModal({ open, title, description, isSubmitting = false, onConfirm, onCancel }) {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-zinc-950/60 transition-opacity duration-150 motion-reduce:transition-none" onClick={isSubmitting ? undefined : onCancel} aria-hidden="true" />
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        aria-describedby="modal-desc"
        data-state="open"
        className="relative z-10 w-full max-w-md max-h-[85dvh] overflow-y-auto rounded-lg border border-zinc-200 bg-white p-6 shadow-xl transition-[transform,opacity] duration-180 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none dark:border-zinc-800 dark:bg-zinc-950"
      >
        <h2 id="modal-title" className="text-base font-semibold tracking-tight text-zinc-900 dark:text-zinc-100">
          {title}
        </h2>
        <p id="modal-desc" className="mt-2 text-sm leading-relaxed text-zinc-600 dark:text-zinc-400 break-words">
          {description}
        </p>
        <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
          <button
            type="button"
            disabled={isSubmitting}
            onClick={onCancel}
            className="min-h-[44px] sm:min-h-[36px] rounded-md border border-zinc-300 bg-white px-4 py-2 text-sm font-medium text-zinc-800 hover:bg-zinc-50 active:scale-[0.97] transition-transform duration-150 disabled:opacity-50 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-200"
          >
            Cancel
          </button>
          <button
            type="button"
            disabled={isSubmitting}
            onClick={onConfirm}
            className="min-h-[44px] sm:min-h-[36px] rounded-md bg-rose-700 px-4 py-2 text-sm font-medium text-white hover:bg-rose-800 active:scale-[0.97] transition-transform duration-150 disabled:opacity-50"
          >
            {isSubmitting ? 'Processing…' : 'Confirm Delete'}
          </button>
        </div>
      </div>
    </div>
  );
}

export function FormField({ id, label, type = 'text', value, onChange, hint, error, required = false, inputMode, autoComplete }) {
  const hintId = hint ? `${id}-hint` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [hintId, errorId].filter(Boolean).join(' ') || undefined;

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
        {label}
        {required && <span className="ml-1 text-rose-600 dark:text-rose-400" aria-hidden="true">*</span>}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        required={required}
        inputMode={inputMode}
        autoComplete={autoComplete}
        value={value}
        onChange={onChange}
        aria-invalid={Boolean(error)}
        aria-describedby={describedBy}
        className={`min-h-[44px] sm:min-h-[38px] w-full rounded-md border bg-white px-3 py-2 text-base sm:text-sm text-zinc-900 placeholder:text-zinc-400 focus:outline-none focus:ring-2 dark:bg-zinc-950 dark:text-zinc-100 ${
          error
            ? 'border-rose-500 focus:border-rose-600 focus:ring-rose-500/20'
            : 'border-zinc-300 focus:border-zinc-900 focus:ring-zinc-900/15 dark:border-zinc-700 dark:focus:border-zinc-300'
        }`}
      />
      {hint && !error && (
        <p id={hintId} className="text-xs text-zinc-500 dark:text-zinc-400">{hint}</p>
      )}
      {error && (
        <p id={errorId} role="alert" className="text-xs font-medium text-rose-700 dark:text-rose-400">
          {error}
        </p>
      )}
    </div>
  );
}

const STATUS_STYLES = {
  draft: 'bg-zinc-100 text-zinc-800 border-zinc-300 dark:bg-zinc-800/80 dark:text-zinc-200 dark:border-zinc-700',
  pending: 'bg-amber-100 text-amber-900 border-amber-300 dark:bg-amber-950/70 dark:text-amber-300 dark:border-amber-800',
  success: 'bg-emerald-100 text-emerald-900 border-emerald-300 dark:bg-emerald-950/70 dark:text-emerald-300 dark:border-emerald-800',
  error: 'bg-rose-100 text-rose-900 border-rose-300 dark:bg-rose-950/70 dark:text-rose-300 dark:border-rose-800',
  info: 'bg-sky-100 text-sky-900 border-sky-300 dark:bg-sky-950/70 dark:text-sky-300 dark:border-sky-800'
};

export function StatusBadge({ status = 'draft', label }) {
  const style = STATUS_STYLES[status] || STATUS_STYLES.draft;
  return (
    <span className={`inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap rounded border px-2 py-0.5 text-xs font-medium tabular-nums ${style}`}>
      <span className="h-1.5 w-1.5 rounded-full bg-current" aria-hidden="true" />
      <span>{label || status}</span>
    </span>
  );
}

export function TelemetryBentoGrid({ primaryKpi, secondaryKpis = [] }) {
  return (
    <section aria-label="Key performance metrics" className="grid grid-cols-1 gap-4 md:grid-cols-3">
      <article className="min-w-0 md:col-span-2 flex flex-col justify-between rounded-lg border border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-950">
        <div className="min-w-0">
          <p className="truncate text-xs font-medium uppercase tracking-wider text-zinc-500 dark:text-zinc-400">
            {primaryKpi.label}
          </p>
          <div className="mt-2 flex flex-wrap items-baseline gap-3">
            <p className="truncate font-mono text-2xl sm:text-3xl font-semibold tracking-tight tabular-nums text-zinc-900 dark:text-zinc-100">
              {primaryKpi.value}
            </p>
            {primaryKpi.delta && (
              <span className="inline-flex items-center rounded border border-emerald-300 bg-emerald-50 px-2 py-0.5 font-mono text-xs font-medium tabular-nums text-emerald-900 dark:border-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300">
                {primaryKpi.delta}
              </span>
            )}
          </div>
        </div>
        <p className="mt-4 truncate text-xs text-zinc-500 dark:text-zinc-400" title={primaryKpi.caption}>
          {primaryKpi.caption}
        </p>
      </article>
      <div className="flex flex-col gap-4 min-w-0">
        {secondaryKpis.map((item) => (
          <article key={item.id} className="min-w-0 flex-1 rounded-lg border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-zinc-950">
            <p className="truncate text-xs font-medium text-zinc-500 dark:text-zinc-400">{item.label}</p>
            <p className="mt-1.5 truncate font-mono text-xl font-semibold tabular-nums text-zinc-900 dark:text-zinc-100">
              {item.value}
            </p>
          </article>
        ))}
      </div>
    </section>
  );
}
